// ---- Fixes to older shapes over Mexico ----------------------------------------------------------
// New Spain is drawn once, by this pack: the Spanish Empire's 'new-spain' (south of 22°N, trimmed
// clear of Guatemala on Day 81) and 'new-spain-north' regions, and Colonial Americas'
// 'new-spain-core', are dropped. Every keyframe still keeps its other regions.
export const MX_DROPS = [['spanish-empire', 'new-spain'], ['spanish-empire', 'new-spain-north'], ['colonial-americas', 'new-spain-core']];
export const mexicoShapeFixes = {
  'spanish-empire': { dropRegions: ['new-spain', 'new-spain-north'] },
  'colonial-americas': { dropRegions: ['new-spain-core'] },
};
/** Apply `mexicoShapeFixes` (throws if a target is missing or a keyframe would be left empty). */
export function applyMexicoShapeFixes(entities) {
  for (const [id, { dropRegions }] of Object.entries(mexicoShapeFixes)) {
    const ent = entities.find((e) => e.id === id);
    if (!ent) throw new Error(`mexico fixes: no entity ${id}`);
    let n = 0;
    for (const kf of ent.overlays) {
      const before = kf.regions.length;
      kf.regions = kf.regions.filter((r) => !dropRegions.includes(typeof r === 'string' ? r : r.id));
      n += before - kf.regions.length;
      if (!kf.regions.length) throw new Error(`mexico fixes: ${id} ${kf.year} left with no region`);
    }
    if (!n) throw new Error(`mexico fixes: ${id} had none of ${dropRegions.join(', ')}`);
  }
}
